   249→
   250→  /* ===== SHADOWS ===== */
   251→  --shadow-xs: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
   252→  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.5), 0 1px 2px -1px rgba(0, 0, 0, 0.5);
   253→  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5), 0 2px 4px -2px rgba(0, 0, 0, 0.5);
   254→  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.5), 0 4px 6px -4px rgba(0, 0, 0, 0.5);
   255→  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
   256→  --shadow-2xl: 0 25px 50px -12px rgba(0, 0, 0, 0.7);
   257→  --shadow-inner: inset 0 2px 4px 0 rgba(0, 0, 0, 0.3);
   258→
   259→  /* Glow Shadows - Primary (Neon Yellow) */
   260→  --glow-primary-sm: 0 0 10px -2px rgba(213, 255, 10, 0.4);
   261→  --glow-primary-md: 0 0 20px -4px rgba(213, 255, 10, 0.5);
   262→  --glow-primary-lg: 0 0 30px -6px rgba(213, 255, 10, 0.6);
   263→  --glow-primary-xl: 0 0 50px -10px rgba(213, 255, 10, 0.5);
   264→  --glow-primary-intense: 0 0 40px rgba(213, 255, 10, 0.8);
   265→
   266→  /* Glow Shadows - Green */
   267→  --glow-green-sm: 0 0 10px -2px rgba(92, 228, 98, 0.4);
